6	import jakarta.servlet.http.HttpServletResponse;
7	import org.springframework.beans.factory.annotation.Value;
8	import org.springframework.stereotype.Component;
9	import org.springframework.web.filter.OncePerRequestFilter;
10	
11	import java.io.IOException;
12	
13	/**
14	 * Validates X-Internal-Token header for internal API endpoints.
15	 * Prevents unauthenticated access to service-to-service endpoints
16	 * when bypassing the gateway.
17	 */
18	@Component
19	public class InternalApiAuthFilter extends OncePerRequestFilter {
20	
21	    private final String internalToken;
22	
23	    public InternalApiAuthFilter(@Value("${internal.token:${INTERNAL_TOKEN:}}") String internalToken) {
24	        this.internalToken = internalToken;
25	    }
26	
27	    @Override
28	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response,
29	                                    FilterChain filterChain) throws ServletException, IOException {
30	        String path = request.getRequestURI();
31	        if (path.contains("/internal/")) {
32	            String token = request.getHeader("X-Internal-Token");
33	            if (internalToken.isEmpty() || !internalToken.equals(token)) {
34	                response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
35	                response.setContentType("application/json;charset=UTF-8");
36	                response.getWriter().write("{\"message\":\"Invalid internal token\"}");
37	                return;
38	            }
39	        }
40	        filterChain.doFilter(request, response);
41	    }
42	}
