38	
39	    /**
40	     * 获取当前用户的通知列表
41	     * GET /api/notifications?page=0&size=20
42	     */
43	    @GetMapping
44	    public ResponseEntity<List<NotificationDTO>> getNotifications(
45	            @RequestParam(defaultValue = "0") @Min(0) int page,
46	            @RequestParam(defaultValue = "20") @Min(1) int size,
