119	    private Long getCurrentUserId(HttpServletRequest request) {
120	        String bearer = request.getHeader("Authorization");
121	        if (bearer != null && bearer.startsWith("Bearer ")) {
122	            String token = bearer.substring(7);
123	            Long userId = jwtUtil.getUserIdFromToken(token);
124	            if (userId != null) {
