1	package com.cc91.fileservice.controller;
2	
3	import com.cc91.fileservice.client.UserServiceClient;
4	import com.cc91.fileservice.dto.ApiResponse;
5	import com.cc91.fileservice.dto.UpdateAvatarRequest;
6	import com.cc91.fileservice.dto.UserInfoDTO;
7	import com.cc91.fileservice.exception.UnauthorizedException;
8	import com.cc91.fileservice.security.JwtUtil;
9	import org.slf4j.Logger;
10	import org.slf4j.LoggerFactory;
11	import org.springframework.http.ResponseEntity;
12	import org.springframework.security.core.Authentication;
13	import org.springframework.security.core.context.SecurityContextHolder;
14	import org.springframework.web.bind.annotation.*;
15	import org.springframework.web.multipart.MultipartFile;
16	
17	import java.io.IOException;
18	import java.nio.file.Files;
19	import java.nio.file.Path;
20	import java.util.List;
21	import java.util.Map;
22	import java.util.UUID;
23	
24	/**
25	 * Handles file uploads for the CC91 forum system.
26	 * Avatar uploads are validated, stored, and the User Service is notified.
27	 * General image uploads are validated and stored locally.
28	 */
29	@RestController
30	@RequestMapping("/api/upload")
31	public class FileUploadController {
32	
33	    private static final Logger logger = LoggerFactory.getLogger(FileUploadController.class);
34	
35	    private static final long MAX_IMAGE_SIZE = 2 * 1024 * 1024; // 2MB
36	    private static final List<String> ALLOWED_CONTENT_TYPES = List.of(
37	            "image/jpeg", "image/png", "image/gif", "image/webp"
38	    );
39	
40	    private final UserServiceClient userServiceClient;
41	    private final JwtUtil jwtUtil;
42	
43	    public FileUploadController(UserServiceClient userServiceClient, JwtUtil jwtUtil) {
44	        this.userServiceClient = userServiceClient;
45	        this.jwtUtil = jwtUtil;
46	    }
47	
48	    /**
49	     * Upload avatar image.
50	     * POST /api/upload/avatar
51	     * Validates the image, stores it under uploads/avatars/, and calls
52	     * User Service via Feign to update the user's avatar URL.
53	     */
54	    @PostMapping("/avatar")
55	    public ResponseEntity<ApiResponse<Map<String, String>>> uploadAvatar(
56	            @RequestParam("file") MultipartFile file
57	    ) throws IOException {
58	        String username = getCurrentUsername();
59	
60	        // Validate file
61	        validateImageFile(file);
62	
63	        // Generate unique filename
64	        String filename = generateFilename(file);
65	
66	        // Save to uploads/avatars/
67	        Path uploadDir = Path.of("uploads/avatars");
68	        Files.createDirectories(uploadDir);
69	        Path filePath = uploadDir.resolve(filename);
70	        file.transferTo(filePath.toFile());
71	
72	        String avatarUrl = "/uploads/avatars/" + filename;
73	
74	        // Call User Service to update avatar URL
75	        Long userId = getCurrentUserId();
76	        if (userId != null) {
77	            try {
78	                userServiceClient.updateAvatar(userId, new UpdateAvatarRequest(avatarUrl));
79	                logger.info("Avatar updated for user {} (userId={})", username, userId);
80	            } catch (Exception ex) {
81	                logger.error("Failed to update avatar in User Service for userId={}: {}", userId, ex.getMessage());
82	                // File is saved, but User Service update failed
83	                // Return success with a warning
84	                return ResponseEntity.ok(ApiResponse.success("Avatar uploaded but profile update may be delayed",
85	                        Map.of("avatarUrl", avatarUrl)));
86	            }
87	        }
88	
89	        return ResponseEntity.ok(ApiResponse.success("Avatar uploaded successfully",
90	                Map.of("avatarUrl", avatarUrl)));
91	    }
92	
93	    /**
94	     * Upload general image.
95	     * POST /api/upload/images
96	     * Validates the image and stores it under uploads/images/.
97	     */
98	    @PostMapping("/images")
99	    public ResponseEntity<ApiResponse<Map<String, String>>> uploadImage(
100	            @RequestParam("file") MultipartFile file
101	    ) throws IOException {
102	        getCurrentUsername(); // Verify authenticated
103	
104	        // Validate file
105	        validateImageFile(file);
106	
107	        // Generate unique filename
108	        String filename = generateFilename(file);
109	
110	        // Save to uploads/images/
111	        Path uploadDir = Path.of("uploads/images");
112	        Files.createDirectories(uploadDir);
113	        Path filePath = uploadDir.resolve(filename);
114	        file.transferTo(filePath.toFile());
115	
116	        String url = "/uploads/images/" + filename;
117	        return ResponseEntity.ok(ApiResponse.success("Upload successful", Map.of("url", url)));
118	    }
119	
120	    /**
121	     * Validates that the uploaded file is an image within size limits.
122	     */
123	    private void validateImageFile(MultipartFile file) {
124	        if (file.isEmpty()) {
125	            throw new IllegalArgumentException("File is empty");
126	        }
127	
128	        String contentType = file.getContentType();
129	        if (contentType == null || !ALLOWED_CONTENT_TYPES.contains(contentType)) {
130	            throw new IllegalArgumentException("Only jpg/png/gif/webp images are supported");
131	        }
132	
133	        if (file.getSize() > MAX_IMAGE_SIZE) {
134	            throw new IllegalArgumentException("File size cannot exceed 2MB");
135	        }
136	    }
137	
138	    /**
139	     * Generates a unique filename preserving the original extension.
